const input = $input.first().json;
const submissionPageId = input.id || '';

// Accept both orchestrator-mapped field names and raw Notion field names.
const clientName = input.client_name || input['Client'] || '';
// Week Of from Notion can be a date string, an ISO timestamp, or a Notion date property object
function extractDateString(v) {
  if (!v) return '';
  if (typeof v === 'string') return v;
  if (typeof v === 'object') {
    return v.start || v.date?.start || v.value || '';
  }
  return String(v);
}
let batchDateRaw = extractDateString(input.batch_date) || extractDateString(input['Week Of']);
let batchDate = batchDateRaw ? batchDateRaw.substring(0, 10) : DateTime.now().toFormat('yyyy-MM-dd');
if (!/^\d{4}-\d{2}-\d{2}$/.test(batchDate)) {
  // Last resort — try Date.parse, fall back to today
  const parsed = new Date(batchDateRaw);
  batchDate = isNaN(parsed.getTime()) ? DateTime.now().toFormat('yyyy-MM-dd') : parsed.toISOString().substring(0, 10);
}
const notesRaw = (input.notes_for_ai || input['Notes for AI'] || '').trim();
const callNumberOverride = input.call_number_override || null;

let specificCallRef = null;
const callNumMatch = notesRaw.match(/(?:use|from|based on|refer to)\s+call\s+(?:#|number\s+)?(\d+)/i);
const dateMatch    = notesRaw.match(/(?:use|from|based on|refer to).*?(?:call|transcript).*?\b((?:jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:tember)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)\s+\d{1,2}(?:st|nd|rd|th)?,?\s*(?:\d{4})?)/i);

if (callNumMatch) {
  specificCallRef = { type: 'call_number', value: callNumMatch[1] };
} else if (dateMatch) {
  specificCallRef = { type: 'date', value: dateMatch[1] };
}

// Detect Grain recording URL pasted into Notes for AI (overrides call selection)
const grainUrlPattern = /https?:\/\/(?:grain\.com|app\.grain\.com)\/(?:share\/recording|recordings?)\/([a-zA-Z0-9_-]+)/i;
const grainUrlMatch = notesRaw.match(grainUrlPattern);
if (grainUrlMatch && !specificCallRef) {
  specificCallRef = { type: 'grain_url', grain_recording_id: grainUrlMatch[1], original_url: grainUrlMatch[0] };
}

// Compute target week (Mon-Sun) containing batchDate, plus previous week for fallback search.
function isoDate(d) { return d.toISOString().substring(0, 10); }
const batchDateObj = new Date(batchDate + 'T00:00:00Z');
if (isNaN(batchDateObj.getTime())) {
  throw new Error('Could not parse batch_date / Week Of value: ' + JSON.stringify(batchDateRaw));
}
const dow = batchDateObj.getUTCDay(); // 0=Sun, 1=Mon, ..., 6=Sat
const daysToMonday = dow === 0 ? -6 : (1 - dow);
const targetMon = new Date(batchDateObj);
targetMon.setUTCDate(batchDateObj.getUTCDate() + daysToMonday);
const targetSun = new Date(targetMon);
targetSun.setUTCDate(targetMon.getUTCDate() + 6);
const prevMon = new Date(targetMon);
prevMon.setUTCDate(targetMon.getUTCDate() - 7);
const prevSun = new Date(targetMon);
prevSun.setUTCDate(targetMon.getUTCDate() - 1);

const cleanName = clientName.replace(/\s*\(.*?\)\s*/g, '').trim();
const callSign  = cleanName.split(/\s+/).filter(w => /^[A-Z]/.test(w)).map(w => w[0]).join('');

return [{
  json: {
    client_name:              clientName,
    batch_date:               batchDate,
    notes_for_ai:             notesRaw,
    call_number_override:     callNumberOverride,
    specific_call_ref:        specificCallRef,
    has_specific_call_override: specificCallRef !== null,
    call_sign:                callSign,
    submission_page_id:       submissionPageId,
    target_week_start:        isoDate(targetMon),
    target_week_end:          isoDate(targetSun),
    prev_week_start:          isoDate(prevMon),
    prev_week_end:            isoDate(prevSun)
  }
}];

const notionResult = $input.first().json;
const preprocess = $('Pre-process Inputs').first().json;

if (!notionResult.results || notionResult.results.length === 0) {
  throw new Error('No client dashboard found for: ' + preprocess.client_name + '. Check the client name matches exactly in Notion.');
}

const dashboard = notionResult.results[0];
const props = dashboard.properties || {};

// Read a Notion property as plain text, regardless of its type.
function readText(p) {
  if (!p) return '';
  if (typeof p === 'string') return p;
  if (p.rich_text?.[0]?.plain_text) return p.rich_text.map(t => t.plain_text).join('');
  if (p.title?.[0]?.plain_text)     return p.title.map(t => t.plain_text).join('');
  if (p.email)                      return p.email;
  if (p.url)                        return p.url;
  if (p.phone_number)               return p.phone_number;
  if (p.select?.name)               return p.select.name;
  if (p.formula?.string)            return p.formula.string;
  if (p.rollup?.string)             return p.rollup.string;
  if (typeof p.number === 'number') return String(p.number);
  return '';
}

const primaryEmail       = readText(props['Primary Email']);
const secondaryEmail     = readText(props['Secondary Email']);
const callSignFromNotion = readText(props['Call Sign']);
const grainSearchName    = readText(props['Grain ID']);
const grainRecordingId   = readText(props['Grain Recording ID']);

return [{
  json: {
    ...preprocess,
    dashboard_page_id: dashboard.id,
    primary_email: primaryEmail,
    secondary_email: secondaryEmail,
    call_sign_override: callSignFromNotion,
    grain_search_name: grainSearchName,
    grain_recording_id: grainRecordingId
  }
}];

const preprocess    = $('Pre-process Inputs').first().json   || {};
const dashboardInfo = $('Extract Dashboard Info').first().json || {};

// Navigation callout (Column 0) — holds the client's databases plus a "Resources" child_page.
const navBlocks = $('Fetch Navigation Callout Content').first().json?.results || [];

// General Pages callout (inside the Resources child_page) — holds the per-client docs:
// Intelligence Brief, Content Strategy Doc, Brand Config, Onboarding Forms, Competitor Tracking.
const generalBlocks = $('Fetch General Pages Callout Content').first().json?.results || [];

let callAgendasId = null;
let masterContentId = null;
let performanceReportsId = null;
let intelBriefPageId = null;
let strategyDocPageId = null;
let brandConfigPageId = null;
let competitorTrackingPageId = null;
let formatBankId = null;

function blockTitle(b) {
  if (b.type === 'child_database') return (b.child_database?.title || '').toLowerCase();
  if (b.type === 'child_page')     return (b.child_page?.title     || '').toLowerCase();
  return '';
}

for (const b of navBlocks) {
  const title = blockTitle(b);
  if (b.type === 'child_database') {
    if (title.includes('call agenda'))         callAgendasId        = b.id;
    if (title.includes('master content'))      masterContentId      = b.id;
    if (title.includes('performance report'))  performanceReportsId = b.id;
    if (title.includes('format bank'))         formatBankId         = b.id;
  }
}

for (const b of generalBlocks) {
  const title = blockTitle(b);
  if (b.type === 'child_page') {
    if (title.includes('intelligence brief'))  intelBriefPageId         = b.id;
    if (title.includes('content strategy'))    strategyDocPageId        = b.id;
    if (title.includes('brand config'))        brandConfigPageId        = b.id;
    if (title.includes('competitor tracking')) competitorTrackingPageId = b.id;
  }
}

const summarize = (arr) => arr.map(b =>
  `${b.type}: "${b.child_database?.title || b.child_page?.title || '(no title)'}" [${b.id}]`
).join(' | ');

const clientName = preprocess.client_name || dashboardInfo.client_name || '';
console.log(`Extract Client DB IDs for "${clientName}"`);
console.log(`Nav callout blocks: ${summarize(navBlocks)}`);
console.log(`General Pages blocks: ${summarize(generalBlocks)}`);

if (!callAgendasId)    throw new Error(`Could not find 'Call Agendas' database for ${clientName}. Nav callout: ${summarize(navBlocks)}`);
if (!masterContentId)  throw new Error(`Could not find 'Master Content Database' for ${clientName}. Nav callout: ${summarize(navBlocks)}`);
if (!intelBriefPageId) throw new Error(`Could not find 'Intelligence Brief' page for ${clientName} inside Resources → General Pages. General Pages: ${summarize(generalBlocks)}`);
if (!strategyDocPageId) throw new Error(`Could not find 'Content Strategy' page for ${clientName} inside Resources → General Pages. General Pages: ${summarize(generalBlocks)}`);

return [{
  json: {
    ...preprocess,
    ...dashboardInfo,
    client_name: clientName,
    call_agendas_db_id: callAgendasId,
    master_content_db_id: masterContentId,
    performance_reports_db_id: performanceReportsId,
    format_bank_db_id: formatBankId,
    intel_brief_page_id: intelBriefPageId,
    strategy_doc_page_id: strategyDocPageId,
    brand_config_page_id: brandConfigPageId,
    competitor_tracking_page_id: competitorTrackingPageId
  }
}];

function blocksToText(blocks) {
  return (blocks || []).map(block => {
    const type = block.type;
    if (!block[type]) return '';
    const richText = block[type].rich_text || block[type].text || [];
    return richText.map(t => t.plain_text || '').join('');
  }).filter(Boolean).join('\n');
}

const dashboardInfo = $('Extract Client DB IDs').first().json;

// allItems[0] = Fetch Intelligence Brief blocks, allItems[1] = Fetch Content Strategy Doc blocks
const allItems = $input.all();
const intelBlocks = allItems[0]?.json?.results || [];
const strategyBlocks = allItems[1]?.json?.results || [];

const intelBriefText = blocksToText(intelBlocks);
const strategyDocText = blocksToText(strategyBlocks);

// Try to extract per-platform counts first (e.g. "X: 14", "LinkedIn: 7")
const linkedinMatch = strategyDocText.match(/linkedin[:\s]+([0-9]+)/i);
const xMatch = strategyDocText.match(/(?:x|twitter)[:\s]+([0-9]+)/i);
const linkedinPosts = linkedinMatch ? parseInt(linkedinMatch[1]) : 0;
const xPosts = xMatch ? parseInt(xMatch[1]) : 0;

// If both platform counts found, sum them; otherwise try generic "N posts per batch/week" pattern
const totalPostsMatch = strategyDocText.match(/(\d+)\s*(?:posts?(?:\/| per )(?:week|batch)|per\s+(?:week|batch))/i);
const totalPostsPerBatch = (xPosts && linkedinPosts)
  ? xPosts + linkedinPosts
  : (totalPostsMatch ? parseInt(totalPostsMatch[1]) : 21);

// Re-derive platform splits if one was missing
const finalLinkedinPosts = linkedinPosts || Math.round(totalPostsPerBatch * 0.33);
const finalXPosts = xPosts || (totalPostsPerBatch - finalLinkedinPosts);

// Ask Claude for 20% more ideas than needed so filtering still yields a full batch
const transcriptQuota = Math.ceil(totalPostsPerBatch * 1.2);

const hasMiscPillar = /miscellaneous/i.test(intelBriefText);

return [{
  json: {
    ...dashboardInfo,
    intel_brief_text: intelBriefText,
    strategy_doc_text: strategyDocText,
    total_posts_per_batch: totalPostsPerBatch,
    linkedin_posts: finalLinkedinPosts,
    x_posts: finalXPosts,
    transcript_idea_quota: transcriptQuota,
    has_misc_pillar: hasMiscPillar
  }
}];

const allItems = $input.all();
const contextData = $('Extract Context and Calculate Quota').first().json;
const preprocess = $('Pre-process Inputs').first().json || {};

const grainRaw = allItems[0]?.json;
const notionRaw = allItems[1]?.json;

const clientName = preprocess.client_name || contextData.client_name || '';
const callSign = contextData.call_sign_override || preprocess.call_sign_override || preprocess.call_sign || contextData.call_sign || '';
const primaryEmail   = (contextData.primary_email   || '').toLowerCase().trim();
const secondaryEmail = (contextData.secondary_email || '').toLowerCase().trim();

const allRecordings = (grainRaw?.recordings || []).filter(c => !!c?.id);
const notionRows = notionRaw?.results || [];

const targetWeekStart = preprocess.target_week_start;
const targetWeekEnd   = preprocess.target_week_end;
const prevWeekStart   = preprocess.prev_week_start;
const prevWeekEnd     = preprocess.prev_week_end;

const allRows = notionRaw?.results || [];
const callNumberOverride = parseInt(preprocess.call_number_override, 10);

function pickRecordingDate(r) {
  if (!r) return '';
  const candidates = [r.start_datetime, r.started_at, r.recorded_at, r.meeting_start_at, r.meeting_started_at, r.record_started_at, r.created_at];
  for (const c of candidates) {
    if (c == null || c === '') continue;
    if (typeof c === 'number') return new Date(c * (c < 1e12 ? 1000 : 1)).toISOString();
    if (typeof c === 'string') return c;
  }
  return '';
}
function recordingDurationSec(r) {
  // Try explicit duration first
  if (typeof r?.duration === 'number') return r.duration;
  if (typeof r?.duration_seconds === 'number') return r.duration_seconds;
  // Compute from start/end
  const start = pickRecordingDate(r);
  const end = r?.end_datetime || r?.ended_at || r?.meeting_end_at || '';
  if (start && end) {
    const s = new Date(start).getTime();
    const e = new Date(end).getTime();
    if (!isNaN(s) && !isNaN(e) && e > s) return Math.round((e - s) / 1000);
  }
  return 0;
}

function rowCallTitle(row) {
  const props = row?.properties || {};
  for (const [, v] of Object.entries(props)) {
    if (v?.type === 'title') {
      const t = (v.title || []).map(rt => rt?.plain_text || '').join('');
      if (t) return t;
    }
  }
  return row?.properties?.['Title']?.title?.[0]?.plain_text
      || row?.properties?.['Name']?.title?.[0]?.plain_text
      || '';
}
function rowCallNumber(row) {
  const m = (rowCallTitle(row) || '').match(/Call\s+(\d+)/i);
  return m ? parseInt(m[1], 10) : 0;
}
function rowCallDate(row) {
  return row?.properties?.['Call Date']?.date?.start || '';
}
function rowTranscriptUrl(row) {
  return row?.properties?.['Transcript URL']?.url
    || row?.properties?.['Transcript Doc']?.url
    || row?.properties?.['Transcript Link']?.url
    || row?.properties?.['Transcript']?.url
    || '';
}
function rowGrainIdText(row) {
  return row?.properties?.['Grain Recording ID']?.rich_text?.[0]?.plain_text
    || row?.properties?.['Grain ID']?.rich_text?.[0]?.plain_text
    || '';
}
function rowContainsGrainId(row, grainId) {
  if (!grainId) return false;
  for (const [, v] of Object.entries(row?.properties || {})) {
    if (!v) continue;
    if (v.type === 'url' && v.url && v.url.includes(grainId)) return true;
    if (v.type === 'rich_text') {
      const t = (v.rich_text || []).map(rt => rt?.plain_text || '').join('');
      if (t.includes(grainId)) return true;
    }
    if (v.type === 'title') {
      const t = (v.title || []).map(rt => rt?.plain_text || '').join('');
      if (t.includes(grainId)) return true;
    }
  }
  return false;
}
function findRowByGrainId(grainId) {
  return notionRows.find(r => rowGrainIdText(r) === grainId || rowContainsGrainId(r, grainId));
}

const maxCallNumber = allRows.reduce((max, r) => Math.max(max, rowCallNumber(r)), 0);
const nextCallNumber = maxCallNumber + 1;
console.log(`Call Agendas has ${allRows.length} row(s), max parsed Call N = ${maxCallNumber}, next would be Call ${nextCallNumber}.`);
console.log(`Client name: "${clientName}"`);

if (!clientName) {
  return [{ json: { ...contextData, abort: true, abort_reason: 'client_name is empty.' } }];
}

function reuseExistingRow(row, source) {
  const transcriptUrl = rowTranscriptUrl(row);
  const existingNum = rowCallNumber(row);
  console.log(`Reusing existing Call Agendas row "${rowCallTitle(row)}" via ${source}.`);
  return [{
    json: {
      ...contextData, abort: false,
      client_name: clientName, call_sign: callSign,
      batch_date: preprocess.batch_date || contextData.batch_date || '',
      agenda_row_id: row.id,
      transcript_doc_url: transcriptUrl,
      call_title: rowCallTitle(row) || 'Untitled Call',
      latest_grain_call_date: rowCallDate(row),
      new_call_number: callNumberOverride > 0 ? callNumberOverride : (existingNum || nextCallNumber),
      use_existing_transcript: !!transcriptUrl,
      used_prev_week: false,
      selection_source: source
    }
  }];
}

// ── Notes override paths (specific call from notes) ─────────────────────────
const notesGrainId = preprocess.specific_call_ref?.type === 'grain_url' ? preprocess.specific_call_ref.grain_recording_id : null;
const dashboardGrainId = contextData.grain_recording_id || '';
const overrideRecordingId = notesGrainId || dashboardGrainId;

if (overrideRecordingId) {
  const existing = findRowByGrainId(overrideRecordingId);
  if (existing && rowTranscriptUrl(existing)) return reuseExistingRow(existing, 'notes_override_matched_existing');
  const specificRec = allRecordings.find(r => r.id === overrideRecordingId);
  if (specificRec) {
    return [{ json: { ...contextData, abort: false, client_name: clientName, call_sign: callSign,
      batch_date: preprocess.batch_date || contextData.batch_date || '',
      latest_grain_call_id: specificRec.id,
      latest_grain_call_title: specificRec.title || 'Recording ' + specificRec.id,
      latest_grain_call_date: pickRecordingDate(specificRec),
      new_call_number: callNumberOverride > 0 ? callNumberOverride : nextCallNumber,
      existing_agenda_row_id: existing ? existing.id : null,
      use_existing_transcript: false, used_prev_week: false, selection_source: 'notes_override' } }];
  }
  return [{ json: { ...contextData, abort: false, client_name: clientName, call_sign: callSign,
    batch_date: preprocess.batch_date || contextData.batch_date || '',
    latest_grain_call_id: overrideRecordingId,
    latest_grain_call_title: 'Recording ' + overrideRecordingId,
    latest_grain_call_date: '',
    new_call_number: callNumberOverride > 0 ? callNumberOverride : nextCallNumber,
    existing_agenda_row_id: existing ? existing.id : null,
    use_existing_transcript: false, used_prev_week: false, selection_source: 'notes_override_id_only' } }];
}

// ── Step 1: Existing in-target-week row with transcript already ────────────
const inTargetWeek = notionRows.filter(r => { const d = rowCallDate(r); return d && d >= targetWeekStart && d <= targetWeekEnd; });
const existingWithTranscript = inTargetWeek.filter(r => rowTranscriptUrl(r)).sort((a, b) => rowCallDate(b).localeCompare(rowCallDate(a)))[0];
if (existingWithTranscript) return reuseExistingRow(existingWithTranscript, 'call_agendas_target_week');

const targetWeekRowWithGrainId = [...inTargetWeek].sort((a, b) => rowCallDate(b).localeCompare(rowCallDate(a))).find(r => rowGrainIdText(r));
if (targetWeekRowWithGrainId) {
  const storedGrainId = rowGrainIdText(targetWeekRowWithGrainId);
  return [{ json: { ...contextData, abort: false, client_name: clientName, call_sign: callSign,
    batch_date: preprocess.batch_date || contextData.batch_date || '',
    latest_grain_call_id: storedGrainId,
    latest_grain_call_title: rowCallTitle(targetWeekRowWithGrainId) || 'Untitled Call',
    latest_grain_call_date: rowCallDate(targetWeekRowWithGrainId),
    new_call_number: callNumberOverride > 0 ? callNumberOverride : (rowCallNumber(targetWeekRowWithGrainId) || nextCallNumber),
    existing_agenda_row_id: targetWeekRowWithGrainId.id,
    use_existing_transcript: false, used_prev_week: false, selection_source: 'call_agendas_grain_id_no_transcript' } }];
}

if (!primaryEmail && !secondaryEmail) {
  return [{ json: { ...contextData, client_name: clientName, call_sign: callSign,
    abort: true, abort_reason: 'No Primary Email or Secondary Email set on ' + clientName + "'s Notion page." } }];
}
if (allRecordings.length === 0) {
  return [{ json: { ...contextData, client_name: clientName, call_sign: callSign, abort: true, abort_reason: 'Grain returned 0 recordings.' } }];
}

const targetEmails = [primaryEmail, secondaryEmail].filter(Boolean);
function recordingHasClient(r) {
  const parts = r.participants || r.participant_list || [];
  return parts.some(p => { const email = (p?.email || '').toLowerCase().trim(); return email && targetEmails.includes(email); });
}
function recordingDateOnly(r) { return (pickRecordingDate(r) || '').substring(0, 10); }

// Skip "dud" calls: anything shorter than this is treated as not substantive (no-show, brief sync, etc.)
// Tune here if needed.
const MIN_DURATION_SEC = 600; // 10 minutes

const candidateClientCalls = allRecordings.filter(recordingHasClient);
const clientCalls = candidateClientCalls.filter(r => {
  const d = recordingDurationSec(r);
  if (d > 0 && d < MIN_DURATION_SEC) {
    console.log(`Skipping dud call ${r.id} (${r.title || ''}) — duration ${d}s < ${MIN_DURATION_SEC}s threshold.`);
    return false;
  }
  return true;
});
console.log(`Client calls before dud filter: ${candidateClientCalls.length}, after: ${clientCalls.length}.`);

function processGrainPick(pick, sourceLabel, usedPrevWeek) {
  const existing = findRowByGrainId(pick.id);
  if (existing && rowTranscriptUrl(existing)) return reuseExistingRow(existing, sourceLabel + '_matched_existing');
  const pickedDate = pickRecordingDate(pick);
  const dur = recordingDurationSec(pick);
  console.log(`${sourceLabel} pick: id=${pick.id}, title="${pick.title || ''}", date=${pickedDate}, duration_sec=${dur}`);
  return [{ json: { ...contextData, abort: false, client_name: clientName, call_sign: callSign,
    batch_date: preprocess.batch_date || contextData.batch_date || '',
    latest_grain_call_id: pick.id,
    latest_grain_call_title: pick.title || '',
    latest_grain_call_date: pickedDate,
    new_call_number: callNumberOverride > 0 ? callNumberOverride : nextCallNumber,
    existing_agenda_row_id: existing ? existing.id : null,
    use_existing_transcript: false, used_prev_week: usedPrevWeek, selection_source: sourceLabel } }];
}

// Pick the LONGEST call in the target week (duration = substance proxy).
// Falls back to longest in prev week, then to most-recent client call overall.
const grainInTargetWeek = clientCalls
  .filter(r => { const d = recordingDateOnly(r); return d && d >= targetWeekStart && d <= targetWeekEnd; })
  .sort((a, b) => recordingDurationSec(b) - recordingDurationSec(a));
if (grainInTargetWeek.length > 0) {
  console.log(`Target-week candidates (${grainInTargetWeek.length}): ` +
    grainInTargetWeek.map(r => `[${pickRecordingDate(r).substring(0,10)} dur=${recordingDurationSec(r)}s] ${r.title || r.id}`).join(' | '));
  return processGrainPick(grainInTargetWeek[0], 'grain_target_week_longest', false);
}

const grainInPrevWeek = clientCalls
  .filter(r => { const d = recordingDateOnly(r); return d && d >= prevWeekStart && d <= prevWeekEnd; })
  .sort((a, b) => recordingDurationSec(b) - recordingDurationSec(a));
if (grainInPrevWeek.length > 0) {
  console.log(`Prev-week candidates (${grainInPrevWeek.length}): ` +
    grainInPrevWeek.map(r => `[${pickRecordingDate(r).substring(0,10)} dur=${recordingDurationSec(r)}s] ${r.title || r.id}`).join(' | '));
  return processGrainPick(grainInPrevWeek[0], 'grain_prev_week_longest', true);
}

// FINAL FALLBACK: most recent client call on or BEFORE the picked week's end date.
// We must not pick a call that took place AFTER the user's chosen Week Of, even if
// such a call exists in Grain.
const cutoff = targetWeekEnd; // YYYY-MM-DD string
const beforeCutoff = clientCalls
  .filter(r => { const d = recordingDateOnly(r); return d && d <= cutoff; })
  .sort((a, b) => new Date(pickRecordingDate(b) || 0) - new Date(pickRecordingDate(a) || 0));
if (beforeCutoff.length > 0) {
  const mostRecent = beforeCutoff[0];
  console.log(`No calls in target/prev week. Falling back to most recent client call on/before ${cutoff}: ${mostRecent.id} (${pickRecordingDate(mostRecent)})`);
  return processGrainPick(mostRecent, 'grain_most_recent_before_cutoff', false);
}
// As a last resort, if the user picked a date in the future or there are literally no past calls
// at all, log clearly and abort. (Do NOT silently use a future call.)
console.log(`No client calls on or before ${cutoff}. ${clientCalls.length} client call(s) exist after that date and were intentionally skipped.`);

return [{ json: { ...contextData, client_name: clientName, call_sign: callSign,
  abort: true,
  abort_reason: 'No client recordings found in Grain at all for ' + clientName + '.' } }];

// Sequential chain: Cross-check → Create Google Doc → Fetch Grain Transcript → here
const crosscheckData = $('Cross-check Dates and Determine Call Number').first().json;
const createdDoc = $('Create Google Doc').first().json;

// Fetch Grain Transcript has continueOnFail=true — check for error
const fetchResult = $input.first().json;
const fetchFailed = !!fetchResult?.error || !!fetchResult?.code;
const transcriptText = fetchFailed ? '' : (fetchResult?.data || '').trim();

if (fetchFailed) {
  console.log('Warning: Grain transcript fetch failed:', JSON.stringify(fetchResult).substring(0, 200));
  console.log('Continuing with empty transcript — the Google Doc will contain a placeholder.');
}

const docId = createdDoc.id || createdDoc.documentId;
if (!docId) throw new Error('doc_id missing. Create Google Doc returned: ' + JSON.stringify(createdDoc));

const docUrl = `https://docs.google.com/document/d/${docId}/edit`;
const safeText = transcriptText || '[Transcript not yet available — add manually]';

return [{
  json: {
    ...crosscheckData,
    doc_id: docId,
    doc_url: docUrl,
    transcript_text: transcriptText,
    batch_update_body: { requests: [{ insertText: { location: { index: 1 }, text: safeText } }] }
  }
}];

const prepData = $('Prepare Transcript for Doc').first().json;
const agendaRow = $('Create Call Agendas Row').first().json;
const preprocess = $('Pre-process Inputs').first().json || {};

// client_name insurance: prepData should have it from Cross-check Dates spread,
// but if any node in the chain dropped it, fall back to Pre-process Inputs directly.
const clientName = prepData.client_name || preprocess.client_name || '';

return [{
  json: {
    ...prepData,
    client_name: clientName,
    agenda_row_id: agendaRow.id,
    transcript_doc_url: prepData.doc_url,
    call_title: 'Call ' + prepData.new_call_number + ' - ' + clientName + ' x Digital Leverage',
    source: 'fresh_fetch'
  }
}];

// Reads directly from Cross-check Dates output (carried through IF nodes)
const data = $input.first().json;
if (!data.transcript_doc_url) {
  throw new Error('use_existing_transcript was true but transcript_doc_url is empty. Call Agendas row may need its Transcript URL filled in for: ' + (data.call_title || data.client_name));
}
return [{
  json: {
    ...data,
    source: 'existing'
  }
}];

const currentData = $('Select Transcript Item').first().json;
const rows = $input.first().json?.results || [];

if (rows.length === 0) throw new Error('Specific call not found. Check the call number or date in Notes for AI.');

const row = rows[0];
const props = row.properties || {};
// Try all known property name variants for transcript URL
const transcriptUrl = props['Transcript URL']?.url
  || props['Transcript Doc']?.url
  || props['Transcript Link']?.url
  || props['Transcript']?.url
  || '';
const callTitle = props['Name']?.title?.[0]?.plain_text
  || props['Title']?.title?.[0]?.plain_text
  || 'Unknown Call';

if (!transcriptUrl) throw new Error(`The requested call "${callTitle}" was found in Call Agendas but has no Transcript URL yet. Add the Google Doc link to the Call Agendas row and re-run.`);

return [{ json: { ...currentData, transcript_doc_url: transcriptUrl, call_title: callTitle, source: 'specific_override' } }];

const contextData = $('Pick Final Transcript').first().json;
const docData = $input.first().json;

function extractDocText(doc) {
  if (!doc.body?.content) return '';
  let text = '';
  for (const el of doc.body.content) {
    if (el.paragraph) {
      for (const e of el.paragraph.elements || []) {
        if (e.textRun) text += e.textRun.content || '';
      }
    }
  }
  return text;
}

return [{ json: { ...contextData, transcript_text: extractDocText(docData) } }];

const ctx = $('Extract Transcript Text').first().json;
const formatBankResult = $('Query Format Bank Pass 1').first().json;
const prevBatch = $('Format Previous Batch Context').first().json || {};

const formatList = (formatBankResult.results || []).map(page => {
  const p = page.properties || {};
  return {
    name: p['Format Name']?.title?.[0]?.plain_text || '',
    description: p['Format Description']?.rich_text?.[0]?.plain_text || '',
    when_to_use: p['When To Use It']?.rich_text?.[0]?.plain_text || '',
    platform: p['Platform']?.select?.name || 'LinkedIn & X/Twitter'
  };
}).filter(f => f.name);

const userPrompt = `CLIENT: ${ctx.client_name}

INTELLIGENCE BRIEF:
${ctx.intel_brief_text}

CONTENT STRATEGY (${ctx.total_posts_per_batch} posts/batch - LinkedIn: ${ctx.linkedin_posts}, X/Twitter: ${ctx.x_posts}):
${ctx.strategy_doc_text}

WRITER'S NOTES FOR THIS BATCH:
${ctx.notes_for_ai || 'None'}

CALL: ${ctx.call_title || 'Most recent call'}

FULL TRANSCRIPT:
${ctx.transcript_text}

---
${prevBatch.previous_batch_block || 'PREVIOUS BATCH IDEAS: None'}

---
FORMAT BANK (name | description | when to use | platform):
${formatList.map(f => `- ${f.name} | ${f.description} | ${f.when_to_use} | ${f.platform}`).join('
')}

---
TARGET: Generate ${ctx.transcript_idea_quota} ideas.

Return ONLY a valid JSON array. No preamble, no markdown. Each element:
{
  "topic": "one word, two words, or one line",
  "one_of_one_opinion": "the unique take only this client can have",
  "content_pillar": "exact pillar name from the strategy doc",
  "transcript_source": "direct quote or clear description of the specific moment this came from",
  "format_candidates": ["Format Name 1", "Format Name 2", "Format Name 3"],
  "platform_lean": "LinkedIn or X/Twitter or Either",
  "notes_for_reviewer": "flags or questions for the human reviewer, empty string if none"
}`;

return [{ json: { ...ctx, format_list: formatList, mine_ideas_user_prompt: userPrompt, previous_batch_idea_count: prevBatch.previous_batch_idea_count || 0 } }];

const ctx = $('Prepare Mine Ideas Context').first().json;
const resp = $input.first().json;
const content = resp.content?.[0]?.text || '';
const stopReason = resp.stop_reason || '';

function stripDashes(s) { return typeof s === 'string' ? s.replace(/[—–]/g, '-') : s; }
function deepStripDashes(obj) {
  if (typeof obj === 'string') return stripDashes(obj);
  if (Array.isArray(obj)) return obj.map(deepStripDashes);
  if (obj && typeof obj === 'object') { const o = {}; for (const k of Object.keys(obj)) o[k] = deepStripDashes(obj[k]); return o; }
  return obj;
}

function parseIdeasArray(text) {
  const m = text.match(/\[\s*\{[\s\S]*\}\s*\]/);
  if (m) { try { return JSON.parse(m[0]); } catch (_) {} }
  const emptyMatch = text.match(/\[\s*\]/);
  if (emptyMatch) { try { return JSON.parse(emptyMatch[0]); } catch (_) {} }
  const start = text.indexOf('[');
  if (start === -1) return null;
  const lastClose = text.lastIndexOf('}');
  if (lastClose <= start) return null;
  try { const p = JSON.parse(text.slice(start, lastClose + 1) + ']'); if (Array.isArray(p)) return p; } catch (e) {
    const prev = text.lastIndexOf('}', lastClose - 1);
    if (prev > start) { try { const p2 = JSON.parse(text.slice(start, prev + 1) + ']'); if (Array.isArray(p2)) return p2; } catch (_) {} }
  }
  return null;
}

let ideas = parseIdeasArray(content);
if (ideas === null) {
  throw new Error('Failed to parse ideas from Claude (stop_reason=' + stopReason + '). Response (first 800 chars): ' + content.substring(0, 800));
}
if (!Array.isArray(ideas) || ideas.length === 0) {
  // Empty result from a substantive call is a genuine failure — let it propagate so the error workflow handles it.
  throw new Error('Claude returned 0 ideas from the transcript (stop_reason=' + stopReason + '). Call was likely off-topic or too brief despite passing the duration filter. Review the transcript.');
}

ideas = deepStripDashes(ideas);
const allFormatNames = [...new Set(ideas.flatMap(i => i.format_candidates || []))];
return [{ json: { ...ctx, raw_ideas: ideas, format_names_needed: allFormatNames } }];

const ctx = $('Parse Ideas and Extract Format Names').first().json;
const formatExamples = $('Query Format Bank Pass 2 Examples').first().json;

const examplesMap = {};
(formatExamples.results || []).forEach(page => {
  const p = page.properties || {};
  const name = p['Format Name']?.title?.[0]?.plain_text || '';
  if (name) {
    examplesMap[name] = {
      name,
      description: p['Format Description']?.rich_text?.[0]?.plain_text || '',
      when_to_use: p['When To Use It']?.rich_text?.[0]?.plain_text || '',
      platform: p['Platform']?.select?.name || 'LinkedIn & X/Twitter',
      example_1: p['Example 1']?.rich_text?.[0]?.plain_text || '',
      example_2: p['Example 2']?.rich_text?.[0]?.plain_text || '',
      example_3: p['Example 3']?.rich_text?.[0]?.plain_text || ''
    };
  }
});

const userPrompt = `CLIENT: ${ctx.client_name}
BATCH: ${ctx.total_posts_per_batch} posts - LinkedIn: ${ctx.linkedin_posts}, X/Twitter: ${ctx.x_posts}
WRITER'S NOTES: ${ctx.notes_for_ai || 'None'}

FORMAT EXAMPLES:
${JSON.stringify(examplesMap, null, 2)}

IDEAS TO FINALIZE:
${JSON.stringify(ctx.raw_ideas, null, 2)}

For each idea: review examples, confirm or upgrade the format, assign final platform, run quality checklist. Remove ideas that fail and cannot be fixed.

Return ONLY valid JSON array. Each element:
{
  "idea": "client-facing row title — combine format descriptor + topic + unique angle as a content pitch note. NEVER start with the client's name (e.g. never 'Bobby said...' or 'I...' — write it like a briefing note). Examples: 'Contrarian belief post about how founders over-analyse angry customers', 'Expanded listicle on the eight UIs that changed how I think about design and why', 'Short-form take on why playing it safe with content is the fastest way to become forgettable'.",
  "topic": "plus or minus 5 words",
  "one_of_one_opinion": "unique take",
  "content_pillar": "exact pillar name",
  "format": "exact format name from Format Bank",
  "platform": "LinkedIn or X/Twitter",
  "sources": "direct quotes from transcript plus explanation of why this works",
  "notes_for_reviewer": "AI flags for human reviewer, empty string if none",
  "passes_checklist": true or false,
  "checklist_issues": "describe issues if false, empty string if true"
}`;

return [{ json: { ...ctx, examples_map: examplesMap, finalize_user_prompt: userPrompt } }];

const ctx = $('Prepare Finalize Ideas Context').first().json;
const resp = $input.first().json;
const content = resp.content?.[0]?.text || '';
const stopReason = resp.stop_reason || '';

function stripDashes(s) { return typeof s === 'string' ? s.replace(/[—–]/g, '-') : s; }
function deepStripDashes(obj) {
  if (typeof obj === 'string') return stripDashes(obj);
  if (Array.isArray(obj)) return obj.map(deepStripDashes);
  if (obj && typeof obj === 'object') { const o = {}; for (const k of Object.keys(obj)) o[k] = deepStripDashes(obj[k]); return o; }
  return obj;
}

function parseIdeasArray(text) {
  const m = text.match(/\[\s*\{[\s\S]*\}\s*\]/);
  if (m) { try { return JSON.parse(m[0]); } catch (_) {} }
  // Recognise an explicit empty array — Claude legitimately returns [] when every idea fails the checklist.
  const emptyMatch = text.match(/\[\s*\]/);
  if (emptyMatch) { try { return JSON.parse(emptyMatch[0]); } catch (_) {} }
  const start = text.indexOf('[');
  if (start === -1) return null;
  const lastClose = text.lastIndexOf('}');
  if (lastClose <= start) return null;
  try { const p = JSON.parse(text.slice(start, lastClose + 1) + ']'); if (Array.isArray(p)) return p; } catch (e) {
    const prev = text.lastIndexOf('}', lastClose - 1);
    if (prev > start) { try { const p2 = JSON.parse(text.slice(start, prev + 1) + ']'); if (Array.isArray(p2)) return p2; } catch (_) {} }
  }
  return null;
}

const finalIdeas = parseIdeasArray(content);

if (finalIdeas === null) {
  throw new Error('Failed to parse finalized ideas (stop_reason=' + stopReason + '). Response (first 800 chars): ' + content.substring(0, 800));
}

if (!Array.isArray(finalIdeas) || finalIdeas.length === 0) {
  // Claude legitimately returned [] — every mined idea failed the quality checklist.
  const rawCount = (ctx.raw_ideas || []).length;
  throw new Error('Finalize Claude rejected all ' + rawCount + ' mined ideas on quality checks. None passed the 365-day / 1-of-1 / pillar / format filters. Review transcript substance or relax Finalize criteria. (stop_reason=' + stopReason + ')');
}

const cleaned = deepStripDashes(finalIdeas);
const passedIdeas = cleaned.filter(i => i.passes_checklist !== false);

if (passedIdeas.length === 0) {
  const failureNotes = cleaned.map((i, idx) => `${idx+1}. ${i.checklist_issues || '(no issues note)'}`).join(' | ');
  throw new Error('Finalize returned ' + cleaned.length + ' ideas but all failed passes_checklist. Issues: ' + failureNotes);
}

return [{ json: { ...ctx, final_ideas: passedIdeas, total_ideas: passedIdeas.length } }];

const ctx = $('Parse Final Ideas').first().json;
const preprocess = $('Pre-process Inputs').first().json || {};
const existingBatches = $input.first().json?.results || [];

function batchPageNumber(page) {
  const props = page.properties || {};
  const titleProp = Object.values(props).find(p => p && p.type === 'title');
  const title = titleProp?.title?.[0]?.plain_text || '';
  const m = title.match(/Batch\s+(\d+)/i);
  return m ? parseInt(m[1], 10) : 0;
}
const maxBatchNumber = existingBatches.reduce((max, p) => Math.max(max, batchPageNumber(p)), 0);
const nextBatchNumber = maxBatchNumber + 1;

const callSign = ctx.call_sign || preprocess.call_sign_override || preprocess.call_sign || '';
const batchName = 'Batch ' + nextBatchNumber + '. ' + callSign + ' x ' + ctx.total_posts_per_batch;

// Recording(s) link — pull the grain call id from whichever upstream node has it.
let grainCallId = '';
try { grainCallId = $('Pick Final Transcript').first().json?.latest_grain_call_id || ''; } catch (_) {}
if (!grainCallId) {
  try { grainCallId = $('Cross-check Dates and Determine Call Number').first().json?.latest_grain_call_id || ''; } catch (_) {}
}
const recordingUrl = grainCallId ? ('https://grain.com/share/recording/' + grainCallId) : '';

return [{ json: { ...ctx, batch_number: nextBatchNumber, batch_name: batchName, recording_url: recordingUrl } }];

const ctx = $('Build Batch Name').first().json;
const batchPage = $('Create Batch Page').first().json;
const postLineupDb = $('Create Post Lineup Overview DB').first().json;

const batchPageId = batchPage.id;
const batchPageUrl = batchPage.url || `https://notion.so/${batchPageId.replace(/-/g, '')}`;
const postLineupDbId = postLineupDb.id;

function normalizePlatform(raw) {
  const r = (raw || '').toLowerCase().trim();
  if (r === 'linkedin') return 'LinkedIn';
  if (r === 'x/twitter' || r === 'x' || r === 'twitter') return 'X/Twitter';
  if (r.includes('twitter') || r.includes('x/twitter')) return 'X/Twitter';
  if (r.includes('linkedin') && !r.includes('twitter')) return 'LinkedIn';
  return 'LinkedIn';
}

const staticData = $getWorkflowStaticData('global');
staticData.batchContext = {
  batch_page_id: batchPageId,
  batch_page_url: batchPageUrl,
  batch_name: ctx.batch_name,
  client_name: ctx.client_name,
  call_title: ctx.call_title || 'Latest Call',
  total_posts_per_batch: ctx.total_posts_per_batch,
  used_prev_week: ctx.used_prev_week === true
};
staticData.createdRows = [];

return ctx.final_ideas.map((idea, index) => ({
  json: {
    ...idea,
    platform: normalizePlatform(idea.platform || idea.platform_lean),
    idea: idea.idea || idea.topic || '(untitled idea)',
    post_lineup_db_id: postLineupDbId,
    batch_page_id: batchPageId,
    batch_page_url: batchPageUrl,
    batch_name: ctx.batch_name,
    client_name: ctx.client_name,
    idea_index: index
  },
  pairedItem: { item: 0 }
}));

const staticData = $getWorkflowStaticData('global');
const ideaData = $('Split Ideas').first().json;
if (!staticData.createdRows) staticData.createdRows = [];
staticData.createdRows.push({
  idea: ideaData.idea,
  platform: ideaData.platform,
  format: ideaData.format,
  content_pillar: ideaData.content_pillar,
  notes_for_reviewer: ideaData.notes_for_reviewer
});
return [{ json: { row_created: true } }];

const staticData = $getWorkflowStaticData('global');
const ctx = staticData.batchContext || {};
const rows = staticData.createdRows || [];

const topIdeas = rows.slice(0, 5).map((r, i) => `${i + 1}. *[${r.platform}]* ${r.idea}`).join('
');
const topNotes = rows.filter(r => r.notes_for_reviewer?.trim()).slice(0, 3).map(r => `- ${r.notes_for_reviewer}`).join('
');

const prevWeekNote = ctx.used_prev_week
  ? '

:warning: *Note:* Used call from previous week — no call found in target week.'
  : '';

const message = `:brain: *New Idea Batch Ready for Review!* <!channel>

*Client:* ${ctx.client_name}
*Batch:* ${ctx.batch_name}
*Source:* Call Transcript - ${ctx.call_title}
*Total Ideas:* ${rows.length}${prevWeekNote}

*Top Ideas:*
${topIdeas}${topNotes ? `

*AI Notes to Review:*
${topNotes}` : ''}

<${ctx.batch_page_url}|View Batch in Notion>`;

return [{ json: { slack_message: message, batch_page_url: ctx.batch_page_url, batch_name: ctx.batch_name, client_name: ctx.client_name, total_ideas: rows.length } }];

const schema = $('Get Call Agendas Schema').first().json;
const summaryData = $input.first().json;
const prepData = $('Prepare Transcript for Doc').first().json;
const dbId = $('Extract Client DB IDs').first().json.call_agendas_db_id;

const schemaProps = schema.properties || {};

const titlePropName = Object.entries(schemaProps).find(([, v]) => v.type === 'title')?.[0] || 'Name';
const datePropName = Object.entries(schemaProps).find(([, v]) => v.type === 'date')?.[0];
const transcriptUrlPropName = Object.entries(schemaProps).find(([k, v]) => v.type === 'url' && k.toLowerCase().includes('transcript'))?.[0]
  || Object.entries(schemaProps).find(([, v]) => v.type === 'url')?.[0];
const recordingUrlPropName = Object.entries(schemaProps).find(([k, v]) => v.type === 'url' && k.toLowerCase().includes('recording'))?.[0];
const summaryPropName = Object.entries(schemaProps).find(([k, v]) => v.type === 'rich_text' && k.toLowerCase().includes('summary'))?.[0];
const topicsPropName = Object.entries(schemaProps).find(([k, v]) => v.type === 'rich_text' && k.toLowerCase().includes('topic'))?.[0];

// Always prefer the full client_name (including any "(Trial)" or other paren suffix) — this is what
// appears in row titles per the user's convention: "Call N - Client (Suffix) x Digital Leverage".
const clientName = prepData.client_name
  || summaryData.client_name
  || $('Pre-process Inputs').first().json?.client_name
  || '?';

const callNum = prepData.new_call_number || summaryData.new_call_number || '?';

const rawCallDate = prepData.latest_grain_call_date || summaryData.latest_grain_call_date || '';
const callDate = rawCallDate ? rawCallDate.split('T')[0] : '';
if (!callDate) console.log('WARNING: no call date — Call Date will be blank.');

const docUrl = prepData.doc_url || summaryData.doc_url;
const grainCallId = prepData.latest_grain_call_id || summaryData.latest_grain_call_id || '';
const recordingUrl = grainCallId ? `https://grain.com/share/recording/${grainCallId}` : null;
const callSummary = summaryData.call_summary || '';
const callTopics = summaryData.call_topics || '';

const rowTitle = 'Call ' + callNum + ' - ' + clientName + ' x Digital Leverage';
console.log(`Building Call Agendas row: title="${rowTitle}", date="${callDate}", grain_call_id="${grainCallId}"`);

const properties = {};
properties[titlePropName] = { title: [{ type: 'text', text: { content: rowTitle } }] };
if (datePropName && callDate) properties[datePropName] = { date: { start: callDate } };
if (transcriptUrlPropName && docUrl) properties[transcriptUrlPropName] = { url: docUrl };
if (recordingUrlPropName && recordingUrl) properties[recordingUrlPropName] = { url: recordingUrl };
if (summaryPropName && callSummary) properties[summaryPropName] = { rich_text: [{ type: 'text', text: { content: callSummary.substring(0, 2000) } }] };
if (topicsPropName && callTopics) properties[topicsPropName] = { rich_text: [{ type: 'text', text: { content: callTopics.substring(0, 2000) } }] };

return [{ json: { row_body: { parent: { database_id: dbId }, properties } } }];

// Debug: log what we're about to send to Notion for Create Idea Row
const item = $input.first().json;
const body = {
  parent: { database_id: item.post_lineup_db_id },
  properties: {
