const claudeResponse = $input.first().json;
const content = claudeResponse.content?.[0]?.text || '';

let summary = '';
let topics = '';
try {
  const match = content.match(/\{[\s\S]*\}/);
  const parsed = JSON.parse(match ? match[0] : content);
  summary = parsed.summary || '';
  const topicsArray = Array.isArray(parsed.topics) ? parsed.topics : [];
  topics = topicsArray.map(t => `• ${t}`).join('\n');
} catch(e) {
  console.log('Warning: Could not parse summary/topics response:', content.substring(0, 200));
}

// Carry through all prepData fields so downstream can access them
const prepData = $('Prepare Transcript for Doc').first().json;

return [{
  json: {
    ...prepData,
    call_summary: summary,
    call_topics: topics
  }
}];

const clientName = $json.client_name || '(unknown client)';
const reason = $json.abort_reason || '(no reason provided)';
const message = ':warning: *Call Transcript to Ideas failed for ' + clientName + '*

*Reason:* ' + reason + '

No transcript was saved and no batch was created. Fix the issue above and re-run.';
return [{ json: { slack_message: message } }];

const pages = $input.all();
const allRecordings = [];
for (const item of pages) {
  const recs = item.json?.recordings || [];
  for (const r of recs) {
    if (r?.id) allRecordings.push(r);
  }
}
console.log('Flattened ' + pages.length + ' Grain page(s) into ' + allRecordings.length + ' recordings.');
return [{ json: { recordings: allRecordings, page_count: pages.length } }];

const batchPageId = $('Create Batch Page').first().json.id;
const blocks = $input.first().json?.results || [];

// Look for a child_database named "Content Lineup" (or legacy "Post Lineup")
const postLineupDb = blocks.find(b => {
  if (b.type !== 'child_database') return false;
  const title = (b.child_database?.title || '').toLowerCase();
  return title.includes('content lineup') || title.includes('post lineup');
});

return [{
  json: {
    id: postLineupDb ? postLineupDb.id : null,
    found: !!postLineupDb,
    batch_page_id: batchPageId
  }
}];

const blocks = $input.first().json?.results || [];
const resources = blocks.find(b => b.type === 'child_page' && (b.child_page?.title || '').toLowerCase().includes('resources'));
if (!resources) {
  throw new Error('Could not find a "Resources" child_page inside the navigation callout. Blocks: ' +
    blocks.map(b => `${b.type}: "${b.child_database?.title || b.child_page?.title || '(no title)'}" [${b.id}]`).join(' | '));
}
return [{ json: { id: resources.id, found: true } }];

const blocks = $input.first().json?.results || [];

// Prefer column_list (the General Pages callout lives inside its columns).
// If a callout exists at the top level (older structure), pass it straight through with a flag.
const columnList = blocks.find(b => b.type === 'column_list');
if (columnList) {
  return [{ json: { id: columnList.id, kind: 'column_list' } }];
}

const topCallout = blocks.find(b => b.type === 'callout');
if (topCallout) {
  return [{ json: { id: topCallout.id, kind: 'callout_direct' } }];
}

throw new Error('Could not find a column_list or callout inside the Resources page. Blocks: ' +
  blocks.map(b => `${b.type} [${b.id}]`).join(' | '));

// Input: result of fetching the Resources page's column_list children (i.e. the column blocks),
// OR a passthrough if the Resources page had a direct callout (no column_list).
const ref = $('Find Resources Column List or Callout').first().json;

if (ref.kind === 'callout_direct') {
  // The "callout" branch — emit a single item carrying the callout ID so the next step fetches it.
  return [{ json: { id: ref.id, _is_callout: true } }];
}

const cols = ($input.first().json?.results || []).filter(b => b.type === 'column');
if (cols.length === 0) {
  throw new Error('column_list inside Resources had no column children.');
}
return cols.map(c => ({ json: { id: c.id, _is_callout: false } }));

// Aggregate every column's children and find the callout whose title text matches "General Pages".
// Resources can have multiple callouts (Brand Suite, General Pages, Bespoke Pages…) — pick by name.
const splitItems = $('Split Resources Columns').all();
if (splitItems.length === 1 && splitItems[0].json?._is_callout) {
  return [{ json: { id: splitItems[0].json.id, source: 'direct' } }];
}

function calloutText(b) {
  if (b.type !== 'callout') return '';
  const rt = b.callout?.rich_text || [];
  return rt.map(t => t?.plain_text || t?.text?.content || '').join('').trim();
}

const allChildren = $input.all();
const seenCallouts = [];

// First pass — exact title match for "General Pages"
for (const item of allChildren) {
  const blocks = item.json?.results || [];
  for (const b of blocks) {
    if (b.type !== 'callout') continue;
    const title = calloutText(b);
    seenCallouts.push({ id: b.id, title });
    if (title.toLowerCase().includes('general pages')) {
      return [{ json: { id: b.id, source: 'column', matched_title: title } }];
    }
  }
}

throw new Error('Could not find a callout titled "General Pages" inside Resources columns. Saw callouts: ' +
  JSON.stringify(seenCallouts));

// Sort all batches by parsed Batch N descending and pick the highest.
// This runs before the current batch has been created, so the highest is the previous batch.
const results = $input.first().json?.results || [];

function parseBatchNum(page) {
  const props = page.properties || {};
  const titleProp = Object.values(props).find(p => p && p.type === 'title');
  const title = titleProp?.title?.[0]?.plain_text || '';
  const m = title.match(/Batch\s+(\d+)/i);
  return { num: m ? parseInt(m[1], 10) : 0, title };
}

const sorted = results
  .map(p => ({ ...parseBatchNum(p), id: p.id }))
  .filter(p => p.num > 0)
  .sort((a, b) => b.num - a.num);

if (sorted.length === 0) {
  console.log('No prior batches found — this is the first batch.');
  return [{ json: { has_previous: false, previous_batch_page_id: 'NO_PREVIOUS', previous_batch_number: 0, previous_batch_title: '' } }];
}

const prev = sorted[0];
console.log(`Previous batch: "${prev.title}" (id=${prev.id})`);
return [{ json: { has_previous: true, previous_batch_page_id: prev.id, previous_batch_number: prev.num, previous_batch_title: prev.title } }];

const prevMeta = $('Find Previous Batch').first().json;
if (!prevMeta.has_previous) {
  return [{ json: { has_previous: false, has_db: false, db_id: '', previous_batch_number: 0, previous_batch_title: '' } }];
}

const blocks = $input.first().json?.results || [];
const db = blocks.find(b =>
  b.type === 'child_database' &&
  /content lineup|post lineup/i.test(b.child_database?.title || '')
);
if (!db) {
  console.log('Previous batch page had no Content Lineup child_database. Blocks: ' +
    blocks.map(b => `${b.type}: "${b.child_database?.title || b.child_page?.title || '?'}"`).join(' | '));
  return [{ json: { has_previous: true, has_db: false, db_id: 'NO_DB', previous_batch_number: prevMeta.previous_batch_number, previous_batch_title: prevMeta.previous_batch_title } }];
}

return [{ json: { has_previous: true, has_db: true, db_id: db.id, previous_batch_number: prevMeta.previous_batch_number, previous_batch_title: prevMeta.previous_batch_title } }];

const prevMeta = $('Find Previous Content Lineup DB').first().json;
const queryResult = $input.first().json;

if (!prevMeta.has_previous || !prevMeta.has_db) {
  const reason = !prevMeta.has_previous ? '(first batch — no previous batch to reference)' : '(previous batch had no Content Lineup database)';
  return [{ json: { previous_batch_block: `PREVIOUS BATCH IDEAS: None ${reason}`, previous_batch_number: prevMeta.previous_batch_number || 0 } }];
}

const rows = queryResult?.results || [];
function plain(rich) { return (rich || []).map(t => t?.plain_text || '').join(''); }
function getProp(props, name) {
  const p = props?.[name];
  if (!p) return '';
  if (p.type === 'title')     return plain(p.title);
  if (p.type === 'rich_text') return plain(p.rich_text);
  if (p.type === 'select')    return p.select?.name || '';
  if (p.type === 'status')    return p.status?.name || '';
  if (p.type === 'multi_select') return (p.multi_select || []).map(o => o.name).join(', ');
  return '';
}

const ideas = rows.map(r => ({
  idea:           getProp(r.properties, 'Idea'),
  status:         getProp(r.properties, 'Status') || getProp(r.properties, 'Review Status'),
  platform:       getProp(r.properties, 'Platform'),
  content_pillar: getProp(r.properties, 'Content Pillar'),
  topic:          getProp(r.properties, 'Topic'),
  format:         getProp(r.properties, 'Format')
})).filter(i => i.idea);

if (ideas.length === 0) {
  return [{ json: { previous_batch_block: `PREVIOUS BATCH IDEAS (Batch ${prevMeta.previous_batch_number}): No rows found.`, previous_batch_number: prevMeta.previous_batch_number } }];
}

const lines = ideas.map((i, idx) => {
  const status = i.status || '(no status)';
  const pillar = i.content_pillar ? ` | pillar: ${i.content_pillar}` : '';
  const topic  = i.topic ? ` | topic: ${i.topic}` : '';
  return `${idx + 1}. [${status}] ${i.idea}${pillar}${topic}`;
}).join('\n');

const block = `PREVIOUS BATCH IDEAS (Batch ${prevMeta.previous_batch_number} - "${prevMeta.previous_batch_title}"):\nThe following ideas were already produced in the most recent prior batch. Apply PREVIOUS BATCH AWARENESS rules from the system prompt.\n\n${lines}`;
console.log(`Formatted ${ideas.length} previous-batch ideas for prompt context.`);
return [{ json: { previous_batch_block: block, previous_batch_number: prevMeta.previous_batch_number, previous_batch_idea_count: ideas.length } }];

// Submission Status Gate
// Only let the workflow run when the Notion row's Status is the "fresh" state.
// The Ideation Launcher DB has these options: pending, processing, done, failed.
// New form submissions arrive with Status = pending (or sometimes null if not defaulted).
// Anything else means another execution has already taken this row — skip silently.

const item = $input.first().json;
const rawStatus = item.Status ?? item.status ?? null;
const statusText = (typeof rawStatus === 'string')
  ? rawStatus.trim().toLowerCase()
  : (rawStatus?.name?.toLowerCase?.() || '');

const allowed = ['', 'pending', 'new'];
const isFresh = allowed.includes(statusText);

if (!isFresh) {
  console.log(`Submission ${item.id} skipped — Status="${rawStatus}" (gate only accepts empty / pending).`);
  return [];
}

console.log(`Submission ${item.id} accepted (Status="${rawStatus ?? 'null'}").`);
return [{ json: item }];

// Normalize Notion Webhook Payload
// n8n's Webhook trigger wraps the incoming request as { headers, query, body }.
// Notion's "Send webhook" automation puts the page object at body.data.

const wrapper = $input.first().json || {};
const body = wrapper.body || wrapper;
const page = body.data || body.page || body;
const props = page.properties || {};

function plain(rich) {
  return (rich || []).map(t => t?.plain_text || t?.text?.content || '').join('');
}

function readProp(p) {
  if (!p) return null;
  switch (p.type) {
    case 'title':            return plain(p.title);
    case 'rich_text':        return plain(p.rich_text);
    case 'select':           return p.select?.name ?? null;
    case 'status':           return p.status?.name ?? null;
    case 'multi_select':     return (p.multi_select || []).map(o => o.name);
    case 'date':             return p.date ?? null;
    case 'checkbox':         return !!p.checkbox;
    case 'number':           return p.number ?? null;
    case 'people':           return (p.people || []).map(per => per.person?.email || per.name || per.id);
    case 'email':            return p.email ?? null;
    case 'phone_number':     return p.phone_number ?? null;
    case 'url':              return p.url ?? null;
    case 'created_time':     return p.created_time ?? null;
    case 'last_edited_time': return p.last_edited_time ?? null;
    case 'formula':          return p.formula?.string ?? p.formula?.number ?? p.formula?.boolean ?? null;
    default: return null;
  }
}

if (!page.id) {
  throw new Error('Webhook payload missing page id. Top-level keys: ' + Object.keys(wrapper).join(', ') +
                  '; body keys: ' + (body && typeof body === 'object' ? Object.keys(body).join(', ') : '(none)'));
}

const flat = { id: page.id };
for (const [key, prop] of Object.entries(props)) {
  flat[key] = readProp(prop);
}

console.log(`Normalized submission ${flat.id} — keys: ${Object.keys(flat).join(', ')}`);
return [{ json: flat }];
